    ["A2", "Je n'ai pas mon ordonnance avec moi, mais je prends ce médicament tous les jours.", ["I don't have my prescription with me, but I take this medicine every day.", "I haven't got my prescription with me, but I take this medication every day.", "I don't have the prescription with me, but I take this medicine daily.", "I haven't brought my prescription, but I take this medicine every day."], [["prescription"],["medicine","medication","drug","tablets","pills"],["every day","daily","each day"]], ["Je n'ai pas mon ordonnance sur moi, mais je prends ce médicament chaque jour.", "Je n'ai pas apporté mon ordonnance, mais je prends ce traitement tous les jours."], [["ordonnance"],["pas"],["medicament*","traitement"],["tous les jours","chaque jour","quotidien*"]], "Britannique : « medicine » ou « medication » ; « a prescription » = une ordonnance."],
    ["B1", "Je suis couvert par une assurance voyage ; avez-vous besoin de mes coordonnées ?", ["I have travel insurance; do you need my details?", "I'm covered by travel insurance; do you need my policy details?", "I've got travel insurance — do you need my details?", "I'm covered by my travel insurance; do you need my information?"], [["insurance","insured","covered"],["travel"],["details","information","policy","number","documents"],["do you need","do you want","would you like"]], ["J'ai une assurance voyage ; avez-vous besoin de mes informations ?", "Je suis assuré pour mon voyage ; voulez-vous mon numéro de contrat ?"], [["assurance","assure*","couvert*"],["voyage"],["coordonnees","informations","numero","contrat","police","references","documents"],["avez vous besoin","voulez vous","souhaitez vous","besoin"]], "« travel insurance » = assurance voyage ; « policy number » = numéro de contrat."],
    ["B1", "Pouvez-vous me donner un reçu détaillé pour que mon assurance me rembourse ?", ["Could you give me an itemised receipt so my insurance can reimburse me?", "Could you give me a detailed receipt so that my insurance will reimburse me?", "Can I have an itemised receipt for my insurance claim?", "Could you give me an itemised receipt so I can claim it back from my insurance?"], [["receipt","invoice","bill"],["itemised","itemized","detailed"],["insurance"],["reimburse*","claim","refund*","pay me back","back"],["give me","can i have","could i have","may i have","send me","email me"]], ["Pouvez-vous me donner une facture détaillée pour que mon assurance me rembourse ?", "Pourriez-vous me remettre un reçu détaillé pour mon remboursement par l'assurance ?"], [["recu","facture","note"],["detaille*","detail"],["assurance"],["rembours*"]], "« itemised » = détaillé ligne par ligne ; « to claim » = demander un remboursement."],
    ["A2", "Avez-vous quelque chose de similaire à ce médicament ? Je suis en voyage.", ["Do you have anything similar to this medicine? I'm travelling.", "Do you have an equivalent of this medicine? I'm travelling.", "Have you got something similar to this medicine? I'm travelling.", "Do you have something like this medicine? I'm travelling."], [["similar","equivalent","like","same","generic"],["medicine","medication","drug"],["do you have","have you got","is there"]], ["Avez-vous un équivalent de ce médicament ? Je suis en voyage.", "Y a-t-il un générique pour ce médicament ? Je voyage."], [["similaire","equivalent*","pareil","meme","generique","ressemble*"],["medicament*","produit"],["avez vous","y a t il","existe"]], "À l'étranger, les marques changent : demandez l'« active ingredient » (principe actif) au pharmacien."]
