    ["A1", "J'ai perdu mon passeport.", ["I've lost my passport.", "I lost my passport.", "I have lost my passport."], [["lost", "lose"], ["passport"]], ["Mon passeport est perdu.", "J'ai égaré mon passeport."], [["perdu", "egare"], ["passeport"]], "« lose » est irrégulier : lose, lost, lost."],
    ["A1", "On m'a volé mon portefeuille.", ["My wallet has been stolen.", "Someone stole my wallet.", "My wallet was stolen.", "I've had my wallet stolen."], [["wallet"], ["stolen", "stole"]], ["Quelqu'un m'a volé mon portefeuille.", "Mon portefeuille a été volé."], [["portefeuille"], ["vol*"]], "steal, stole, stolen ; « rob » se dit d'une personne volée."],
    ["A2", "Je voudrais signaler un vol à la police.", ["I'd like to report a theft to the police.", "I want to report a theft to the police.", "I'd like to report a theft.", "I need to report a theft to the police."], [["report"], ["theft"]], ["Je souhaite déclarer un vol.", "Je veux porter plainte pour vol."], [["signaler", "declarer", "porter plainte"], ["vol"]], "« theft » = le vol (le fait) ; « thief » = le voleur."],
    ["A2", "Pouvez-vous appeler un médecin ? C'est urgent.", ["Could you call a doctor? It's urgent.", "Please call a doctor — it's an emergency.", "Can you get a doctor, please? It's urgent.", "I need a doctor urgently."], [["doctor"], ["urgent*", "emergency"]], ["Appelez un médecin, c'est une urgence !", "J'ai besoin d'un médecin tout de suite."], [["medecin"], ["urgent*", "urgence", "tout de suite"]], "« emergency » = urgence."],
    ["A2", "Je suis perdu et mon téléphone n'a plus de batterie.", ["I'm lost and my phone has run out of battery.", "I'm lost and my phone is out of battery.", "I'm lost and my phone's battery is dead.", "I'm lost and my phone has died."], [["lost"], ["phone"], ["battery", "died", "dead"]], ["Je suis perdu et mon téléphone est à plat.", "Je suis perdu, et mon portable est déchargé."], [["perdu"], ["telephone", "portable"], ["batterie", "plat", "decharge*"]], "« run out of » = ne plus avoir de."],
    ["B1", "Mon enfant s'est cogné la tête, il faut voir un médecin.", ["My child hit his head, and we need to see a doctor.", "My child has banged his head. We need a doctor.", "My child has knocked his head — we need to see a doctor."], [["child", "kid"], ["head"], ["hit", "banged", "knocked", "bumped"], ["doctor"]], ["Mon enfant s'est tapé la tête, nous devons voir un docteur.", "Mon enfant a reçu un coup à la tête, il faut un médecin."], [["enfant"], ["tete"], ["medecin", "docteur"]], "« hit », « bang » ou « bump » one's head : mots courants pour un choc."],
    ["B1", "J'ai eu un accident ; je ne suis pas blessé, mais ma voiture est endommagée.", ["I've had an accident. I'm not hurt, but my car is damaged.", "I've been in an accident — I'm not injured, but my car is damaged.", "I had an accident. I'm fine, but my car's damaged.", "I've had a crash. I'm not hurt, but my car is damaged."], [["accident", "crash"], ["hurt", "injured", "fine"], ["car", "car's"], ["damaged"]], ["J'ai eu un accident ; je vais bien, mais ma voiture est abîmée.", "J'ai eu un accrochage, je ne suis pas blessé mais la voiture est endommagée."], [["accident", "accrochage"], ["voiture"], ["endommage*", "abime*"]], "« hurt » = blessé légèrement ; « injured » = blessé plus sérieusement."],
    ["B1", "Il y a une fuite d'eau dans la chambre, pouvez-vous envoyer quelqu'un tout de suite ?", ["There's a water leak in the room. Can you send someone right away?", "There is a leak in the room — could you send someone immediately?", "Water is leaking into the room. Could someone come right now, please?", "There's a leak in my room. Please send someone straight away."], [["leak*"], ["room"], ["send", "come"], ["right away", "immediately", "now", "straight away"]], ["Il y a une fuite dans ma chambre, envoyez quelqu'un immédiatement.", "De l'eau coule dans la chambre, quelqu'un peut venir maintenant ?"], [["fuite", "coule"], ["chambre"], ["envoyer", "envoyez", "venir"]], "« right away » et « straight away » = tout de suite."],
    ["B1", "J'ai besoin d'un interprète ; je ne parle pas bien anglais.", ["I need an interpreter — my English isn't good.", "I need an interpreter. I don't speak English very well.", "Could I have an interpreter, please? I don't speak much English.", "Is there an interpreter? I don't speak English well."], [["interpreter", "translator"], ["english"]], ["Il me faut un interprète, mon anglais n'est pas bon.", "Pourriez-vous trouver un interprète ? Je parle mal l'anglais."], [["interprete", "traducteur"], ["anglais"]], "« interpreter » = à l'oral ; « translator » = à l'écrit."],
    ["A2", "Mon passeport a été volé, où se trouve le consulat de France ?", ["My passport has been stolen. Where is the French consulate?","My passport was stolen — where's the French consulate?","Someone stole my passport. Where is the French embassy?"], [["passport"],["stolen","stole"],["consulate","embassy"],["french","france"]], ["On m'a volé mon passeport, où est le consulat de France ?","Mon passeport est volé ; où est le consulat français ?"], [["passeport"],["vol*"],["consulat","ambassade"]], "« consulate » (consulat) ≠ « embassy » (ambassade)."],
    ["B1", "Je me sens très mal, je vais m'évanouir.", ["I feel unwell — I think I'm going to faint.", "I feel really unwell. I think I'm about to faint.", "I feel ill and I think I'm going to pass out.", "I feel faint, I think I'm going to pass out."], [["faint", "pass out", "collapse"], ["feel", "unwell", "ill"]], ["Je me sens mal, je crois que je vais m'évanouir.", "Je me sens faible, je vais tomber dans les pommes."], [["evanou*", "pommes", "malaise"], ["sens", "mal"]], "« faint » ou « pass out » = s'évanouir."]
