    ["A2", "J'ai un pneu crevé ; pouvez-vous m'aider à changer la roue ?", ["I've got a flat tyre; could you help me change the wheel?", "I have a puncture. Could you help me change the wheel?", "I've got a puncture — could you help me change the tyre?", "I've got a flat tyre. Can you help me change the wheel?"], [["tyre*","tire*","puncture","flat","wheel"],["help*","hand"],["change","changing","fix","replace"]], ["J'ai crevé ; pouvez-vous m'aider à changer la roue ?", "J'ai une crevaison, pouvez-vous me donner un coup de main pour changer le pneu ?"], [["pneu","roue","creve*","crevaison"],["aider","aide","coup de main"],["changer","remplacer"]], "Britannique : « tyre » ; américain : « tire »."],
    ["B1", "J'ai suivi le GPS, mais je me suis trompé de sortie.", ["I followed the satnav, but I took the wrong exit.", "I followed the sat nav, but I took the wrong turning.", "I was following the satnav, but I missed my exit.", "I followed the GPS but took the wrong exit."], [["satnav","sat nav","gps","navigation"],["wrong","missed","miss"],["exit","turning","turn","junction"]], ["J'ai suivi le GPS mais j'ai raté la sortie.", "J'ai suivi le GPS, mais je me suis trompé de route."], [["gps","navigat*"],["tromp*","rate","manque*","loupe*"],["sortie","embranchement","route"]], "« satnav » (britannique) = GPS ; « junction » = échangeur, carrefour."],
    ["B1", "J'ai eu un accrochage ; voici mes coordonnées et mon attestation d'assurance.", ["I've had a minor collision; here are my details and my insurance certificate.", "I've had a bump — here are my details and my insurance papers.", "There's been a minor accident; here are my details and my insurance documents.", "I've had a scrape; here are my contact details and my insurance."], [["accident","collision","bump","scrape","prang"],["details","detail","contact"],["insurance"],["here","my card","my details"]], ["J'ai eu un petit accident ; voici mes coordonnées et mes papiers d'assurance.", "Il y a eu un accrochage ; voici mes coordonnées et mon assurance."], [["accrochage","accident","collision","choc"],["coordonnees","details","infos","informations"],["assurance"],["voici","voila","mes","mon"]], "« a bump » ou « a scrape » = un petit accrochage ; « details » = coordonnées."],
    ["A1", "Pouvez-vous me conduire à la gare ?", ["Could you take me to the station, please?", "Can you take me to the station, please?", "To the station, please.", "Could you drive me to the station, please?"], [["station"],["take me","drive me","bring me","to"]], ["Pouvez-vous m'emmener à la gare, s'il vous plaît ?", "À la gare, s'il vous plaît."], [["gare"],["conduire","emmener","amener","deposer","a la gare"]], "En taxi : « To the station, please » suffit."],
    ["A2", "Combien coûte la course jusqu'à l'aéroport ?", ["How much is the fare to the airport?", "How much is a taxi to the airport?", "How much will it cost to get to the airport?", "How much does it cost to go to the airport by taxi?", "What's the fare to the airport?"], [["how much","fare","cost*"],["airport"],["taxi","fare","cab","to the airport"]], ["C'est combien pour aller à l'aéroport en taxi ?", "Quel est le tarif du taxi pour l'aéroport ?"], [["combien","prix","tarif","coute*"],["aeroport"],["course","taxi","trajet","jusqu","aller"]], "« fare » = le prix du trajet ; « cab » = taxi (familier)."]
