/** Élisions françaises (« l'essayer », « d'accord ») : un mot-clé reste reconnu collé à son article élidé. */
const ELISIONS = ["l'", "d'", "m'", "s'", "n'", "j'", "c'", "qu'", "t'"];
const withElisions = (concepts: string[][]): string[][] =>
  concepts.map((group) => [...group, ...group.filter((word) => !word.includes(" ")).flatMap((word) => ELISIONS.map((elision) => `${elision}${word}`))]);
/** Génitif et contractions en « 's » (« car's », « today's »). */
const withPossessive = (concepts: string[][]): string[][] =>
  concepts.map((group) => [...group, ...group.filter((word) => !word.includes(" ") && !word.endsWith("*") && !word.includes("'")).map((word) => `${word}'s`)]);

export const EN_PHRASES: PhraseItem[] = EN_PHRASE_SITUATIONS.flatMap((situation) =>
  (SITUATION_ROWS[situation.id] ?? []).map(([level, fr, targets, keys, frVariants, frKeys, note], index): PhraseItem => ({
    id: `en-ph-${situation.id}-${String(index + 1).padStart(3, "0")}`,
    situation: situation.id,
    level,
    fr,
    frVariants,
    targets,
    keys: withPossessive(keys),
    frKeys: withElisions(frKeys),
    note
  }))
);
